@extends('layouts.app')
@section('content')<div class="editor-shell"><aside class="toolbox"><h2>استودیو تایپ</h2><label class="upload">افزودن فایل<input id="source" type="file" accept="image/*,.pdf,.zip"></label><button id="analyze" class="btn primary" disabled>تبدیل با هوش مصنوعی</button><div class="stats"><span>صفحات <b id="pages">۰</b></span><span>قیمت <b id="price">۰ ریال</b></span></div><div id="issues"></div><button data-export="docx" class="btn ghost">خروجی Word</button><button data-export="pdf" class="btn ghost">خروجی PDF</button></aside><section class="workspace"><div class="toolbar"><button data-cmd="bold"><b>B</b></button><button data-cmd="italic"><i>I</i></button><button data-cmd="underline"><u>U</u></button><select id="font"><option>B Nazanin</option><option>Vazirmatn</option><option>Tahoma</option></select><select id="size"><option>16</option><option>14</option><option>18</option><option>20</option></select><span class="locked">متن فقط از مسیر خروجی قابل دریافت است</span></div><div id="page" class="paper" contenteditable="true" spellcheck="false"></div></section></div>@endsection
@push('scripts')<script>window.FARAST_EDITOR=true;let docId=null;const source=document.getElementById('source'),an=document.getElementById('analyze'),page=document.getElementById('page'),csrf=document.querySelector('meta[name=csrf-token]').content;source.onchange=()=>an.disabled=!source.files.length;an.onclick=async()=>{let fd=new FormData();fd.append('source',source.files[0]);let up=await fetch('/editor/upload',{method:'POST',headers:{'X-CSRF-TOKEN':csrf},body:fd});let uj=await up.json();let r=await fetch('/editor/analyze',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({path:uj.path,mime:uj.mime})});let j=await r.json();if(!r.ok){alert(j.message||'پردازش ناموفق بود');return;}docId=j.document_id;page.innerText=j.text||'';document.getElementById('pages').textContent=j.pages;document.getElementById('price').textContent=new Intl.NumberFormat('fa-IR').format(j.price)+' ریال';renderIssues(j.issues||[]);};function renderIssues(xs){document.getElementById('issues').innerHTML=xs.map((x,i)=>`<div class="issue" data-i="${i}"><mark>${x.word||''}</mark><div>${(x.suggestions||[]).map(s=>`<button type="button" data-s="${s}">${s}</button>`).join('')}</div></div>`).join('');document.querySelectorAll('.issue button').forEach(b=>b.onclick=()=>{const p=b.closest('.issue');p.outerHTML=b.dataset.s;});}document.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>document.execCommand(b.dataset.cmd));document.getElementById('font').onchange=e=>document.execCommand('fontName',false,e.target.value);document.getElementById('size').onchange=e=>document.execCommand('fontSize',false,3);setInterval(()=>fetch('/editor/heartbeat',{method:'POST',headers:{'X-CSRF-TOKEN':csrf}}),60000);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{if(!docId)return alert('ابتدا فایل را پردازش کنید');await fetch('/editor/save',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({document_id:docId,content:page.innerText})});let f=document.createElement('form');f.method='POST';f.action='/editor/export/'+b.dataset.export;f.innerHTML='<input type="hidden" name="_token" value="'+csrf+'"><input type="hidden" name="document_id" value="'+docId+'">';document.body.appendChild(f);f.submit();});</script>@endpush
